package routes

import (
	"encoding/json"
	"net/http"
	"strings"

	"github.com/juancruzestevez/auth-service/auth"
	"github.com/juancruzestevez/auth-service/db"
	"github.com/juancruzestevez/auth-service/dto"
	"github.com/juancruzestevez/auth-service/models"

	"golang.org/x/crypto/bcrypt"
)

func GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("GetUsersHandler"))
}

func GetUserHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("GetUserHandler"))
}

// RegisterHandler maneja el registro de nuevos usuarios
func RegisterHandler(w http.ResponseWriter, r *http.Request) {
	var req dto.RegisterRequest

	// Decodificar el JSON del body
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON format", http.StatusBadRequest)
		return
	}

	// Validar campos requeridos
	if req.Email == "" || req.Password == "" || req.FirstName == "" || req.LastName == "" || req.Nickname == "" {
		http.Error(w, "All fields are required", http.StatusBadRequest)
		return
	}

	// Normalizar el email
	req.Email = strings.TrimSpace(strings.ToLower(req.Email))

	// Verificar si el usuario ya existe
	var existingUser models.User
	if err := db.DB.Where("email = ?", req.Email).First(&existingUser).Error; err == nil {
		http.Error(w, "User with this email already exists", http.StatusConflict)
		return
	}

	// Verificar si el nickname ya existe
	if err := db.DB.Where("nickname = ?", req.Nickname).First(&existingUser).Error; err == nil {
		http.Error(w, "User with this nickname already exists", http.StatusConflict)
		return
	}

	// Hashear la contraseña
	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
	if err != nil {
		http.Error(w, "Failed to process password", http.StatusInternalServerError)
		return
	}

	// Crear el nuevo usuario
	user := models.User{
		FirstName: req.FirstName,
		LastName:  req.LastName,
		Nickname:  req.Nickname,
		Email:     req.Email,
		Password:  string(hashedPassword),
	}

	// Guardar en la base de datos
	if err := db.DB.Create(&user).Error; err != nil {
		http.Error(w, "Failed to create user", http.StatusInternalServerError)
		return
	}

	// Generar JWT token
	token, expiresAt, err := auth.GenerateToken(user.ID, user.Email)
	if err != nil {
		http.Error(w, "Failed to generate token", http.StatusInternalServerError)
		return
	}

	// Preparar respuesta
	response := dto.AuthResponse{
		Token:     token,
		ExpiresAt: expiresAt,
		User: dto.UserResponse{
			ID:        user.ID,
			FirstName: user.FirstName,
			LastName:  user.LastName,
			Nickname:  user.Nickname,
			Email:     user.Email,
		},
	}

	// Enviar respuesta
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(response)
}

// LoginHandler maneja el login de usuarios
func LoginHandler(w http.ResponseWriter, r *http.Request) {
	var req dto.LoginRequest

	// Decodificar el JSON del body
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON format", http.StatusBadRequest)
		return
	}

	// Validar campos requeridos
	if req.Email == "" || req.Password == "" {
		http.Error(w, "Email and password are required", http.StatusBadRequest)
		return
	}

	// Normalizar el email
	req.Email = strings.TrimSpace(strings.ToLower(req.Email))

	// Buscar el usuario en la base de datos
	var user models.User
	if err := db.DB.Where("email = ?", req.Email).First(&user).Error; err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Verificar la contraseña
	if err := bcrypt.CompareHashAndPassword([]byte(user.Password), []byte(req.Password)); err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Generar JWT token
	token, expiresAt, err := auth.GenerateToken(user.ID, user.Email)
	if err != nil {
		http.Error(w, "Failed to generate token", http.StatusInternalServerError)
		return
	}

	// Preparar respuesta
	response := dto.AuthResponse{
		Token:     token,
		ExpiresAt: expiresAt,
		User: dto.UserResponse{
			ID:        user.ID,
			FirstName: user.FirstName,
			LastName:  user.LastName,
			Nickname:  user.Nickname,
			Email:     user.Email,
		},
	}

	// Enviar respuesta
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// PostUsersHandler - mantener para compatibilidad si lo usas para algo más
func PostUsersHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("PostUsersHandler"))
}

func DeleteUsersHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("DeleteUsersHandler"))
}

package main

import (
	"fmt"
	"log"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
)

func main() {
	// Test direct connection with hardcoded values
	dsn := "host=127.0.0.1 user=postgres password=postgres123 dbname=auth_service port=5432 sslmode=disable TimeZone=UTC"

	fmt.Printf("Testing connection with DSN: %s\n", dsn)

	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
		log.Printf("Failed to connect: %v", err)
	} else {
		log.Println("Connection successful!")

		// Test the connection with a simple query
		var result struct {
			Version string
		}
		db.Raw("SELECT version() as version").Scan(&result)
		fmt.Printf("PostgreSQL version: %s\n", result.Version)
	}
}

package main

import (
	"fmt"
	"log"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
)

func main() {
	// Test connection to default postgres database first
	dsn := "host=127.0.0.1 user=postgres password=postgres123 dbname=postgres port=5432 sslmode=disable TimeZone=UTC"

	fmt.Printf("Testing connection to default postgres database...\n")

	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
		log.Printf("Failed to connect to postgres DB: %v", err)
	} else {
		log.Println("Connected to postgres database successfully!")

		// List all databases
		var databases []string
		db.Raw("SELECT datname FROM pg_database WHERE datistemplate = false").Scan(&databases)
		fmt.Printf("Available databases: %v\n", databases)
	}
}
